                stack.extend(clause)
            else:
                continue  # This is a simplified heuristic
        return len(stack)

    def k_theoretic_index(cnf):
        n = len(cnf[0])
        B = [[0] * n for _ in range(n)]
        for clause in cnf:
            for x in clause:
                if x > 0:
                    B[x-1][x-1] += 1
                else:
                    B[-x-1][-x-1] += 1
        det = determinant(B)
        return abs(det) ** (1/n)

    def determinant(matrix):
        n = len(matrix)
        if n == 1:
            return matrix[0][0]
        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            det += (-1) ** j * matrix[0][j] * determinant(submatrix)
        return det

    def is_valid_cnf(cnf, n):
